const PORTAL_B64="";
function b64ToUtf8(s){const bin=atob(s);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return new TextDecoder().decode(bytes);}
export default{async fetch(request,env){const url=new URL(request.url);if(request.method==="OPTIONS")return new Response(null,{headers:{"Access-Control-Allow-Origin":"*"}});const path=url.pathname.replace(/\/+$/,"")||"/";if(path==="/health")return Response.json({status:"ok",service:"stratamesh-portal",version:"1.1.3-diag",size:PORTAL_B64.length});return new Response(b64ToUtf8(PORTAL_B64),{headers:{"Content-Type":"text/html;charset=utf-8","Cache-Control":"no-store","Access-Control-Allow-Origin":"*"}});}};
